import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernels for fused Linear+GELU and optimized Softmax
fused_linear_gelu_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_linear_gelu_kernel(const float* x, const float* weight, const float* bias, float* out, 
                                         int batch_size, int in_features, int out_features) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;

    if (row >= batch_size || col >= out_features) return;

    float sum = 0.0f;
    for (int k = 0; k < in_features; ++k) {
        sum += x[row * in_features + k] * weight[col * in_features + k];
    }
    sum += bias[col];

    // GELU approximation
    float gelu = sum * 0.5f * (1.0f + tanhf(0.7978845608f * (sum + 0.044715f * sum * sum * sum)));

    out[row * out_features + col] = gelu;
}

torch::Tensor fused_linear_gelu_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    int batch_size = x.size(0);
    int in_features = x.size(1);
    int out_features = weight.size(0);

    auto out = torch::zeros({batch_size, out_features}, x.options());

    dim3 threads(16, 16);
    dim3 blocks((batch_size + threads.x - 1) / threads.x, (out_features + threads.y - 1) / threads.y);

    fused_linear_gelu_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        in_features,
        out_features
    );

    return out;
}
"""

softmax_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void softmax_kernel(const float* x, float* out, int batch_size, int features) {
    extern __shared__ float sdata[];

    int row = blockIdx.x;
    int tid = threadIdx.x;
    int step = blockDim.x;

    float max_val = -INFINITY;
    for (int i = tid; i < features; i += step) {
        max_val = fmaxf(max_val, x[row * features + i]);
    }

    // Reduce max within the block
    sdata[tid] = max_val;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] = fmaxf(sdata[tid], sdata[tid + s]);
        }
        __syncthreads();
    }

    max_val = sdata[0];
    __syncthreads();

    // Compute sum of exp(x - max_val)
    float sum = 0.0f;
    for (int i = tid; i < features; i += step) {
        sum += expf(x[row * features + i] - max_val);
    }

    sdata[tid] = sum;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    sum = sdata[0];

    // Normalize and write to out
    for (int i = tid; i < features; i += step) {
        out[row * features + i] = expf(x[row * features + i] - max_val) / sum;
    }
}

torch::Tensor custom_softmax_cuda(torch::Tensor x, int dim) {
    auto out = torch::zeros_like(x);
    int batch_size = x.size(0);
    int features = x.size(1);

    int threads = min(features, 1024);
    int blocks = batch_size;

    size_t shared_mem_size = threads * sizeof(float);
    softmax_kernel<<<blocks, threads, shared_mem_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        features
    );

    return out;
}
"""

# Load CUDA extensions
fused_linear_gelu = load_inline(
    name='fused_linear_gelu',
    cpp_sources="torch::Tensor fused_linear_gelu_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias);",
    cuda_sources=fused_linear_gelu_source,
    functions=['fused_linear_gelu_cuda'],
    verbose=True
)

custom_softmax = load_inline(
    name='custom_softmax',
    cpp_sources="torch::Tensor custom_softmax_cuda(torch::Tensor x, int dim);",
    cuda_sources=softmax_source,
    functions=['custom_softmax_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features):
        super(ModelNew, self).__init__()
        self.in_features = in_features
        self.out_features = out_features

        self.weight = nn.Parameter(torch.Tensor(out_features, in_features))
        self.bias = nn.Parameter(torch.Tensor(out_features))
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        x = fused_linear_gelu.fused_linear_gelu_cuda(x, self.weight, self.bias)
        x = custom_softmax.custom_softmax_cuda(x, dim=1)
        return x
